struct You {
  var heart: Heart?
}
struct Heart {
  var place: Place?
}
struct Place {
  var me: Me?
}
struct Me {}

let you: You? = nil
let _ = you?.heart?.place?.me

void main() {
  float weight = gl_FragCoord.x / 512.0;
  if (weight > 0.5)
    discard;
  gl_FragColor = vec4(1.0, 1.0, 1.0, 1.0);
}
